package org.brightstats.desktop;
import java.util.*;
import java.util.function.*;
import com.google.gson.*;
import javafx.geometry.Insets;
import javafx.scene.control.*;
import javafx.scene.layout.*;
import javafx.stage.Window;
import org.brightstats.data.WorkspaceStore;

final class WorkspaceDialog {
    interface Context {boolean maySwitch();void open(String id)throws Exception;JsonObject current();String currentName();String currentId();void saved(String id);void renamed(String id,String name);void detached(String id);}
    private interface Operation{void run()throws Exception;}
    private final Dialog<Void> dialog=new Dialog<>();private final ListView<WorkspaceStore.Project> projects=new ListView<>();private final Label status=new Label();private final WorkspaceStore store;private final Context context;
    private final Button create=UiAppearance.button("New empty project"),add=UiAppearance.button("Add current project"),save=UiAppearance.button("Save current"),open=UiAppearance.button("Open selected"),rename=UiAppearance.button("Rename"),duplicate=UiAppearance.button("Duplicate saved project"),remove=UiAppearance.button("Remove from list");
    private BiFunction<String,String,Optional<String>> names=this::name;
    private WorkspaceDialog(Window owner,WorkspaceStore store,Context context){this.store=store;this.context=context;dialog.initOwner(owner);dialog.setTitle("Workspace");dialog.setResizable(true);dialog.getDialogPane().getButtonTypes().add(ButtonType.CLOSE);projects.setPrefSize(470,340);projects.setCellFactory(list->new ListCell<>(){@Override protected void updateItem(WorkspaceStore.Project project,boolean empty){super.updateItem(project,empty);setText(empty||project==null?null:project.name()+(project.id().equals(context.currentId())?"  [open]":""));}});projects.setOnMouseClicked(event->{if(event.getClickCount()==2)open.fire();});var commands=new FlowPane(8,8,create,add,save,open,rename,duplicate,remove);Label location=new Label(store.root().toString());location.setWrapText(true);Label note=UiAppearance.label("Projects share this folder, not live datasets. Saves retain a previous version in history. Removing a project from the list keeps its file on disk. Duplicating uses its last saved version.");note.setWrapText(true);status.setWrapText(true);var content=new VBox(10,location,projects,commands,note,status);content.setPadding(new Insets(12));dialog.getDialogPane().setContent(content);
        create.setOnAction(event->guard(()->{var name=names.apply("New project","Untitled");if(name.isEmpty()||!context.maySwitch())return;var project=store.add(name.get(),WorkspaceStore.emptyProject());context.open(project.id());dialog.close();}));add.setOnAction(event->guard(()->{var name=names.apply("Add current project",context.currentName());if(name.isEmpty())return;var project=store.add(name.get(),context.current());context.saved(project.id());refresh(project.id());status.setText("Current project saved in this workspace.");}));save.setOnAction(event->guard(()->{store.save(context.currentId(),context.current());context.saved(context.currentId());refresh(context.currentId());status.setText("Saved. The previous version remains in the workspace history folder.");}));open.setOnAction(event->guard(()->{var selected=selected();if(!context.maySwitch())return;context.open(selected.id());dialog.close();}));rename.setOnAction(event->guard(()->{var selected=selected();var name=names.apply("Rename project",selected.name());if(name.isEmpty())return;store.rename(selected.id(),name.get());context.renamed(selected.id(),name.get());refresh(selected.id());}));duplicate.setOnAction(event->guard(()->{var selected=selected();var name=names.apply("Duplicate last saved project",selected.name()+" copy");if(name.isEmpty())return;String active=store.manifest().active();var copy=store.duplicate(selected.id(),name.get());if(!active.isEmpty())store.activate(active);refresh(copy.id());status.setText("Independent saved copy created. Open it when ready.");}));remove.setOnAction(event->guard(()->{var selected=selected();store.remove(selected.id());context.detached(selected.id());refresh("");status.setText("Removed from the list; the project file is still in the projects folder.");}));projects.getSelectionModel().selectedItemProperty().addListener((observable,old,value)->buttons());refresh(context.currentId());}
    private Optional<String> name(String title,String initial){TextInputDialog input=new TextInputDialog(initial);input.initOwner(dialog.getDialogPane().getScene().getWindow());input.setTitle(title);input.setHeaderText("Project name");return input.showAndWait();}
    private WorkspaceStore.Project selected(){var selected=projects.getSelectionModel().getSelectedItem();if(selected==null)throw new IllegalArgumentException("Select a project.");return selected;}
    private void refresh(String id){projects.getItems().setAll(store.manifest().projects());projects.getItems().stream().filter(project->project.id().equals(id)).findFirst().ifPresent(project->projects.getSelectionModel().select(project));buttons();}
    private void buttons(){boolean empty=projects.getSelectionModel().getSelectedItem()==null;open.setDisable(empty);rename.setDisable(empty);duplicate.setDisable(empty);remove.setDisable(empty);save.setDisable(store.manifest().projects().stream().noneMatch(project->project.id().equals(context.currentId())));}
    private void guard(Operation operation){try{operation.run();}catch(Exception problem){status.setText(problem.getMessage()==null?problem.getClass().getSimpleName():problem.getMessage());}}
    static void show(Window owner,WorkspaceStore store,Context context){new WorkspaceDialog(owner,store,context).dialog.showAndWait();}
    static void smoke(Window owner,WorkspaceStore store,Context context,java.nio.file.Path screenshot)throws Exception{var editor=new WorkspaceDialog(owner,store,context);var choices=new ArrayDeque<>(List.of("GUI current","GUI renamed","GUI duplicate"));editor.names=(title,initial)->Optional.of(choices.removeFirst());editor.dialog.show();editor.add.fire();if(store.manifest().projects().size()!=1||editor.save.isDisable())throw new AssertionError("Workspace add/save controls failed");editor.rename.fire();if(!store.manifest().projects().getFirst().name().equals("GUI renamed"))throw new AssertionError("Workspace rename failed");editor.duplicate.fire();if(store.manifest().projects().size()!=2)throw new AssertionError("Workspace duplicate failed");editor.remove.fire();if(store.manifest().projects().size()!=1)throw new AssertionError("Workspace logical removal failed");editor.save.fire();if(!editor.status.getText().startsWith("Saved."))throw new AssertionError("Workspace save failed: "+editor.status.getText());editor.dialog.getDialogPane().applyCss();editor.dialog.getDialogPane().layout();java.nio.file.Files.deleteIfExists(screenshot);GraphicExport.png(screenshot,editor.dialog.getDialogPane(),1);editor.dialog.close();}
}
